'use strict';
const app=document.querySelector('#app'), modal=document.querySelector('#modal');
const C=window.CKL_CATEGORIES,B=window.CKL_BANK,M=window.CKL_MILESTONES;
const titles={farm:'Grow Together',time:'The CKL Time Machine',wheel:'The Heritage Wheel'};
let state=null,clock=null,spinTimer=null,sound=false,audioContext=null,runId=0;
const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function read(key,fallback){try{return JSON.parse(localStorage.getItem('ckl120-'+key))??fallback}catch{return fallback}}
function write(key,value){try{localStorage.setItem('ckl120-'+key,JSON.stringify(value));return true}catch{return false}}
function shuffle(a){return [...a].sort(()=>Math.random()-.5)}
function sample(a){return a[Math.floor(Math.random()*a.length)]}
function say(s){$('#live').textContent=s}
function tone(good=true){if(!sound)return;try{audioContext??=new(window.AudioContext||window.webkitAudioContext)();audioContext.resume();const o=audioContext.createOscillator(),g=audioContext.createGain();o.connect(g);g.connect(audioContext.destination);o.frequency.value=good?660:220;g.gain.setValueAtTime(.08,audioContext.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+.22);o.start();o.stop(audioContext.currentTime+.22)}catch{}}
function cleanup(){clearInterval(clock);clearTimeout(spinTimer);clock=null;spinTimer=null;runId++}
function farmSVG(level=5){
 const tree=(x,y,s=1)=>`<g transform="translate(${x} ${y}) scale(${s})"><path d="M0 0v-48" stroke="#64523a" stroke-width="7"/><path d="M0-20l-20-20m20 11l24-22" stroke="#64523a" stroke-width="4"/><ellipse cx="0" cy="-55" rx="37" ry="20" fill="#466243"/><ellipse cx="-24" cy="-46" rx="29" ry="17" fill="#5b754b"/><ellipse cx="27" cy="-47" rx="29" ry="17" fill="#627f4e"/></g>`;
 const cow=(x,y)=>`<g transform="translate(${x} ${y})"><ellipse cy="9" rx="23" ry="6" fill="#25432e22"/><path d="M-16 0v13m25-13v13" stroke="#403b30" stroke-width="4"/><path d="M-19-10q-9-7-9 6" fill="none" stroke="#403b30" stroke-width="2"/><rect x="-21" y="-17" width="43" height="23" rx="8" fill="#f8f4df"/><path d="M-15-16q14-3 13 11l-10 5zM10-15q8-1 9 13l-12-3z" fill="#3a3e33"/><path d="M20-17l13 3-1 20-11-3z" fill="#f8f4df"/><path d="M24-17l-4-6m12 9 6-5" stroke="#bba174" stroke-width="2"/></g>`;
 let rows='';for(let i=0;i<8;i++)rows+=`<path d="M${105+i*23} ${216+i*6}l-77 52" stroke="${i%2?'#b0b968':'#829753'}" stroke-width="9" stroke-linecap="round"/>`;
 return `<svg class="farm-svg" viewBox="0 0 640 350" role="img" aria-label="An illustrated Kenyan farm with ${level>1?'growing crops, animals and trees':'space to grow'}"><defs><linearGradient id="land${level}" x2="0" y2="1"><stop stop-color="#ced9b6"/><stop offset="1" stop-color="#91a871"/></linearGradient></defs><ellipse cx="330" cy="295" rx="280" ry="33" fill="#637d4920"/><path d="M35 198L316 69l290 123-285 140z" fill="url(#land${level})"/><path d="M35 198v20l286 134v-20z" fill="#819666"/><path d="M321 332l285-140v20L321 352z" fill="#607b50"/><path d="M292 117l-40 35 42 36-41 31 75 42 55-39 53 25" fill="none" stroke="#e4d2a6" stroke-width="24"/><path d="M298 119l-40 35 42 35-41 31 70 36 52-39 56 24" fill="none" stroke="#f1dfb8" stroke-width="13"/>${tree(480,157,1.1)}${tree(122,201,.7)}<g><path d="M321 110v55l73 31 57-28v-55l-72-31z" fill="#e8ddba"/><path d="M394 140v56l57-28v-55z" fill="#c3bf9f"/><path d="M305 111l72-57 92 58-77 37z" fill="#944d37"/><path d="M377 54l16 95 76-37z" fill="#753c30"/><path d="M345 145v28l24 10v-28z" fill="#76816a"/><path d="M412 145v31l19-9v-30z" fill="#596953"/><path d="M336 127l13 6v14l-13-6zm27 12 13 6v14l-13-6" fill="#bda36d"/></g>${level>0?`<g class="farm-new">${rows}</g>`:''}${level>1?`<g class="farm-new">${cow(424,231)}${cow(477,207)}</g>`:''}${level>2?`<g class="farm-new"><path d="M170 146v38l46 21 39-19v-40l-44-21z" fill="#e9dcb2"/><path d="M160 148l51-46 55 44-49 25z" fill="#b8783e"/><path d="M198 166v29l22 10v-30z" fill="#69543a"/><circle cx="185" cy="159" r="5" fill="#8d805f"/><path d="M242 204l6 2-2 9-6-2zm15 9 6 2-2 9-6-2z" fill="#a96432"/></g>`:''}${level>3?`<g class="farm-new">${tree(326,286,.65)}${tree(543,187,.65)}${tree(85,218,.6)}</g>`:''}${level>4?`<g class="farm-new"><path d="M355 266l65 29 61-31-62-26z" fill="#b8cfdb"/><path d="M369 268l38 16m18-26 25 11" stroke="#e4ece7" stroke-width="3"/><path d="M525 230v-25m-18 33v-26m-17 34v-25m-17 33v-26" stroke="#d9cba4" stroke-width="4"/><path d="M473 237l52-27" stroke="#d9cba4" stroke-width="3"/></g>`:''}</svg>`;
}
function home(){cleanup();state=null;app.innerHTML=`<section class="hero"><div><span class="eyebrow red">120 YEARS OF GROWING TOGETHER</span><h1>A little play.<br>A lasting <em>legacy.</em></h1><p>From our first chapter to the farms of tomorrow. Discover the stories, grow something good, and celebrate with CKL.</p><div class="hero-note"><span>THREE WAYS TO PLAY</span><span>ONE SHARED STORY</span></div></div><div class="anniversary"><div class="anniversary-type"><strong>120</strong><span>YEARS, STILL GROWING.</span></div>${farmSVG(5)}<div class="anniversary-seal">KENYAN ROOTS<b>Since 1906</b>AFRICAN FUTURE</div></div></section><section class="selection"><div class="section-line"><span>FIND YOUR NEXT ADVENTURE</span><span>Quick rounds. Curious minds welcome.</span></div><div class="cards"><button class="card" data-game="farm"><div class="card-art">${farmSVG(5)}</div><div class="card-copy"><span class="eyebrow">BUILD · DISCOVER · GROW</span><h3>Grow Together</h3><p>Big things start small. Turn your knowledge into a thriving little farm.</p><div class="card-foot"><span>5 challenges · About 2 min</span><span class="play-label">Let's grow</span></div></div></button><button class="card" data-game="time"><div class="card-art time-art"><span class="year-coin">1852</span><span class="year-coin">1906</span><span class="year-coin">2021</span></div><div class="card-copy"><span class="eyebrow">TRAVEL · CONNECT · DISCOVER</span><h3>The CKL Time Machine</h3><p>A remarkable journey. Find the dates and the stories that shaped us.</p><div class="card-foot"><span>6 chapters · About 4 min</span><span class="play-label">Step inside</span></div></div></button><button class="card" data-game="wheel"><div class="card-art wheel-art"><div class="mini-wheel"></div></div><div class="card-copy"><span class="eyebrow">SPIN · GUESS · REVEAL</span><h3>The Heritage Wheel</h3><p>Eight themes. Plenty of surprises. Let the wheel choose your story.</p><div class="card-foot"><span>5 spins · About 2 min</span><span class="play-label">Take a spin</span></div></div></button></div></section><section class="bottom-strip"><div><strong>Our next chapter starts with care.</strong><p>Make a tree-growing pledge and vote for where a future forest could take root.</p></div><button class="quiet" id="care">Leave a little good</button></section>`;app.querySelectorAll('[data-game]').forEach(b=>b.onclick=()=>intro(b.dataset.game));$('#care').onclick=care;window.scrollTo(0,0)}
function intro(mode){cleanup();state=null;const copy={farm:['A little knowledge.<br>A lot of growth.','Answer five questions to grow your farm. Every correct answer unlocks something new: crops, livestock, a poultry house, trees, then a pond.',['5 challenges','20 seconds each','Up to 1,000 points']],time:['Step back.<br>Discover what grew.','Visit six chapters of the CKL story. Find the year of each milestone, then uncover a story from that chapter.',['6 chapters','25 seconds per challenge','Up to 1,000 points']],wheel:['A good story<br>at every turn.','Spin to choose one of eight anniversary themes, then answer a question. Your knowledge earns the points; the wheel brings the surprises.',['5 spins','25 seconds per question','Up to 1,000 points']]};const [heading,text,rules]=copy[mode];app.innerHTML=`<section class="screen"><button class="quiet" id="back">All games</button><div class="intro"><span class="eyebrow red">${titles[mode]}</span><h1>${heading}</h1><div class="intro-art ${mode==='wheel'?'wheel-art':mode==='time'?'time-art':''}">${mode==='farm'?farmSVG(3):mode==='wheel'?'<div class="mini-wheel"></div>':'<span class="year-coin">1852</span><span class="year-coin">1906</span><span class="year-coin">2021</span>'}</div><p>${text}</p><div class="rules">${rules.map(r=>`<span>${r}</span>`).join('')}</div><button class="primary" id="start">${mode==='farm'?'Plant the first seed':mode==='time'?'Start the journey':'Let’s spin'}</button>${mode==='wheel'?'<p class="mini-label">This is a knowledge game. No prizes are configured.</p>':''}</div></section>`;$('#back').onclick=home;$('#start').onclick=()=>start(mode);window.scrollTo(0,0)}
function start(mode){cleanup();state={mode,round:0,correct:0,answered:0,total:mode==='time'?12:5,used:new Set(),growth:0,phase:mode==='time'?'year':'question',angle:0,saved:false};if(mode==='farm'){const cats=shuffle([0,1,2,3,4,5,6,7]).slice(0,5);state.questions=cats.map(cat=>({cat,q:sample(B[cat])}))}if(mode==='time')state.questions=M.map(m=>({cat:m.cat,q:sample(B[m.cat])}));renderGame()}
function score(){return Math.round(state.correct/state.total*1000)}
function gameTop(){return `<div class="game-top"><button class="quiet" id="exit">All games</button><div class="game-title"><span class="eyebrow red">${state.mode==='farm'?'BUILD SOMETHING GOOD':state.mode==='time'?'A JOURNEY THROUGH OUR STORY':'EIGHT THEMES. ONE SHARED LEGACY.'}</span><h2>${titles[state.mode]}</h2></div><div class="metrics"><span>${state.mode==='time'?'Chapter':'Round'}<b>${state.round+1} / ${state.mode==='time'?6:5}</b></span><span>Points<b id="points">${score()}</b></span><span id="timer-box">Time<b id="timer">—</b></span></div></div>`}
function renderGame(){clearInterval(clock);app.innerHTML=`<section class="screen">${gameTop()}<div class="game-layout" id="game-body"></div></section>`;$('#exit').onclick=exitGame;if(state.mode==='farm')renderFarm();if(state.mode==='time')renderTime();if(state.mode==='wheel')renderWheel();window.scrollTo(0,0)}
function exitGame(){clearInterval(clock);$('#modal-content').innerHTML='<h2>Leave this round?</h2><p>Your current game will end. Saved high scores will stay on this device.</p><div class="result-actions" style="margin-top:20px"><button class="primary" id="leave">Leave game</button><button class="quiet" id="stay">Keep playing</button></div>';modal.showModal();$('#leave').onclick=()=>{modal.close();home()};$('#stay').onclick=()=>modal.close();modal.onclose=()=>{modal.onclose=null;if(state&&!state.locked&&state.deadline)startTimer(state.remaining||1)};}
function timer(seconds,callback){state.remaining=seconds;state.expire=callback;state.deadline=Date.now()+seconds*1000;startTimer(seconds)}
function startTimer(seconds){clearInterval(clock);state.deadline=Date.now()+seconds*1000;function tick(){if(!state)return;state.remaining=Math.max(0,Math.ceil((state.deadline-Date.now())/1000));const node=$('#timer');if(node){node.textContent=state.remaining+'s';node.style.color=state.remaining<=5?'var(--red)':''}if(state.remaining===0){clearInterval(clock);state.expire()}}tick();if(state.remaining>0&&!modal.open)clock=setInterval(tick,200)}
function renderFarm(){const upgrades=['Room to grow','Crops in the ground','A healthier herd','A place for poultry','A greener tomorrow','A thriving little farm'];$('#game-body').innerHTML=`<div class="stage"><div class="stage-caption"><span class="eyebrow">YOUR FARM, TAKING SHAPE</span><h3 id="farm-name">${upgrades[state.growth]}</h3><p id="farm-caption">${state.growth?'Your knowledge is making a difference. Keep growing.':'Every good farm starts with a little possibility.'}</p></div><div id="farm-scene">${farmSVG(state.growth)}</div><span class="map-badge" id="farm-badge">${state.growth} / 5 farm additions</span></div><div class="panel" id="challenge"></div>`;question(state.questions[state.round]);}
function renderTime(){const m=M[state.round];$('#game-body').innerHTML=`<div class="timeline-stage"><span class="eyebrow">CHAPTER ${state.round+1} OF 6</span><div class="big-year" id="chapter-year">${state.phase==='year'?'????':m.year}</div><h3>${m.title}</h3><p>${m.text}</p><div class="timeline-track">${M.map((_,i)=>`<span class="${i<=state.round?'done':''}"></span>`).join('')}</div></div><div class="panel" id="challenge"></div>`;if(state.phase==='year'){let years=shuffle(M.map(m=>m.year).filter(y=>y!==m.year)).slice(0,2);years=shuffle([...years,m.year]);$('#challenge').innerHTML=`<span class="eyebrow red">SET THE TIME MACHINE</span><h3 class="question">Which year belongs to this chapter?</h3><div class="year-options">${years.map(y=>`<button class="year-button" data-year="${y}">${y}</button>`).join('')}</div><div id="feedback" aria-live="polite"></div>`;state.locked=false;document.querySelectorAll('[data-year]').forEach(b=>b.onclick=()=>answerYear(Number(b.dataset.year)));timer(25,()=>answerYear(null))}else question(state.questions[state.round])}
function showAnswer({good,timeout,category,selected,correct,explanation,label,next}){
 const dialog=document.querySelector('#answer-modal');
 dialog.className='answer-modal '+(good?'is-correct':timeout?'is-timeout':'is-incorrect');
 dialog.innerHTML=`<div class="lesson-status"><span class="lesson-icon" aria-hidden="true">${good?'&#10003;':timeout?'&#9201;':'!'}</span><span class="eyebrow">${esc(category)}</span></div><h2 id="lesson-title">${good?'That is correct!':timeout?'Time is up.':'A little discovery.'}</h2><p class="lesson-intro">${good?'You know your CKL story. Here is a little more.':'Every answer is a chance to learn something new.'}</p>${!good&&selected!==null?`<div class="your-answer"><span>Your answer</span><p>${esc(selected)}</p></div>`:''}<div class="lesson-answer"><span>${good?'Correct answer':'The correct answer'}</span><h3>${esc(correct)}</h3></div><div class="lesson-story"><span class="eyebrow">THE STORY BEHIND IT</span><p>${esc(explanation)}</p></div><button class="primary" id="next" autofocus>${esc(label)}</button>`;
 dialog.showModal();
 document.querySelector('#next').onclick=()=>{dialog.close();next()};
}
function answerYear(year){if(state.locked)return;state.locked=true;clearInterval(clock);const m=M[state.round],good=year===m.year;state.answered++;if(good)state.correct++;tone(good);$('#points').textContent=score();$('#chapter-year').textContent=m.year;document.querySelectorAll('[data-year]').forEach(b=>{b.disabled=true;if(Number(b.dataset.year)===m.year)b.classList.add('correct');else if(Number(b.dataset.year)===year)b.classList.add('wrong')});showAnswer({good,timeout:year===null,category:'The CKL Time Machine',selected:year,correct:m.year,explanation:m.text,label:'Continue to the story',next:()=>{state.phase='question';renderGame()}});say(good?'Correct year':'The year was '+m.year)}
function question(item){state.locked=false;state.item=item;const [q,choices]=item.q;$('#challenge').innerHTML=`<span class="eyebrow red">${C[item.cat]}</span><div class="progress"><span style="width:${state.round/(state.mode==='time'?6:5)*100}%"></span></div><h3 class="question">${esc(q)}</h3><div class="answers">${choices.map((s,i)=>`<button class="answer" data-answer="${i}"><span class="letter">${String.fromCharCode(65+i)}</span><span>${esc(s)}</span></button>`).join('')}</div><div id="feedback" aria-live="polite"></div>`;document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>answer(Number(b.dataset.answer)));timer(state.mode==='farm'?20:25,()=>answer(null))}
function answer(index){if(state.locked)return;state.locked=true;clearInterval(clock);const q=state.item.q,good=index===q[2];state.answered++;if(good)state.correct++;tone(good);$('#points').textContent=score();document.querySelectorAll('[data-answer]').forEach(b=>{b.disabled=true;if(Number(b.dataset.answer)===q[2])b.classList.add('correct');else if(Number(b.dataset.answer)===index)b.classList.add('wrong')});if(state.mode==='farm'&&good){state.growth++;$('#farm-scene').innerHTML=farmSVG(state.growth);$('#farm-badge').textContent=state.growth+' / 5 farm additions';$('#farm-name').textContent=['','Crops in the ground','A healthier herd','A place for poultry','A greener tomorrow','A thriving little farm'][state.growth];$('#farm-caption').textContent='A new addition, thanks to your knowledge.'}const last=state.round===(state.mode==='time'?5:4);showAnswer({good,timeout:index===null,category:C[state.item.cat],selected:index===null?null:q[1][index],correct:q[1][q[2]],explanation:q[3],label:last?'Continue to my results':'Continue',next:()=>{state.round++;if(last)finish();else{state.phase=state.mode==='time'?'year':'question';renderGame()}}});say(good?'Correct answer':'The correct answer is '+q[1][q[2]])}
function wheelSVG(){let slices='';const labels=['Where it','Coming home','CKL','Made','Made in','Brands farmers','Growing','Caring for'];const sub=['all began','to Kenya','surprises','Kenyan','Kenya','trust','together','the land'];for(let i=0;i<8;i++){let a=(i*45-90)*Math.PI/180,b=((i+1)*45-90)*Math.PI/180,mid=(i*45+22.5-90)*Math.PI/180;let x=200+183*Math.cos(a),y=200+183*Math.sin(a),xx=200+183*Math.cos(b),yy=200+183*Math.sin(b),tx=200+125*Math.cos(mid),ty=200+125*Math.sin(mid);slices+=`<path d="M200 200L${x} ${y}A183 183 0 0 1 ${xx} ${yy}Z" fill="${i%2?'#795235':'#a67542'}" stroke="#d6b477" stroke-width="1.5"/><text x="${tx}" y="${ty-5}" text-anchor="middle" fill="#fff0cc" font-family="Georgia" font-size="13" transform="rotate(${i*45+22.5} ${tx} ${ty})"><tspan x="${tx}">${labels[i]}</tspan><tspan x="${tx}" dy="17">${sub[i]}</tspan></text>`}return `<svg id="wheel" viewBox="0 0 400 400" role="img" aria-label="Wooden wheel with eight CKL story categories"><circle cx="200" cy="200" r="196" fill="#4b3223" stroke="#ba985c" stroke-width="4"/>${slices}${Array.from({length:16},(_,i)=>`<circle cx="${200+190*Math.cos(i*Math.PI/8)}" cy="${200+190*Math.sin(i*Math.PI/8)}" r="3" fill="#ddc18a"/>`).join('')}</svg>`}
function renderWheel(){state.locked=true;state.deadline=null;$('#timer').textContent='—';$('#game-body').innerHTML=`<div class="wheel-stage"><div class="wheel-wrap"><div class="wheel-pointer"></div>${wheelSVG()}<div class="wheel-hub"><small>120 YEARS</small>SPIN &<br>DISCOVER</div></div></div><div class="panel spin-panel" id="challenge"><span class="eyebrow red">A NEW TURN IN OUR STORY</span><h3>Where will you land?</h3><p>From unexpected beginnings to Kenyan-made pride, every theme has a story worth discovering.</p><button class="primary" id="spin">Spin the wheel</button><div class="category-grid">${C.map(c=>`<span>${c}</span>`).join('')}</div><p class="mini-label">Knowledge points only · No prize draw</p></div>`;$('#wheel').style.transform=`rotate(${state.angle}deg)`;$('#spin').onclick=spin}
function spin(){const button=$('#spin');if(button.disabled)return;button.disabled=true;button.textContent='Finding your story…';const available=B.flatMap((bank,cat)=>bank.map((q,i)=>({cat,q,key:cat+'-'+i}))).filter(x=>!state.used.has(x.key));const item=sample(available);state.used.add(item.key);const base=(360-(item.cat*45+22.5))%360;state.angle=(Math.floor(state.angle/360)+5)*360+base;$('#wheel').style.transform=`rotate(${state.angle}deg)`;tone();const id=runId;spinTimer=setTimeout(()=>{if(id!==runId||!state)return;question(item);say('The wheel selected '+C[item.cat])},matchMedia('(prefers-reduced-motion: reduce)').matches?100:3500)}
function finish(){clearInterval(clock);state.locked=true;const points=score(),mode=state.mode;const medal=points>=800?'A legacy champion':points>=500?'A growing expert':'A curious explorer';app.innerHTML=`<section class="screen"><div class="result"><span class="eyebrow red">${titles[mode]} · ROUND COMPLETE</span><h2>${mode==='farm'?'Look what you helped grow.':mode==='time'?'You’ve travelled quite a way.':'Every turn tells a story.'}</h2>${mode==='farm'?farmSVG(state.growth):'<div class="result-score">'+points+'<small> / 1,000</small></div>'}<div class="result-medal">${medal}</div><div class="result-stats"><span><b>${points}</b>Points earned</span><span><b>${state.correct} / ${state.total}</b>Correct answers</span>${mode==='farm'?`<span><b>${state.growth}</b>Farm additions</span>`:''}</div><p>One more chapter in 120 years of growing together. Save your first name to this device’s high scores.</p><form id="save-score"><label class="sr-only" for="player-name">First name</label><input id="player-name" maxlength="24" placeholder="Your first name" autocomplete="given-name" required><button class="primary">Save my score</button></form><div id="save-message" role="status"></div><div class="result-actions"><button class="primary" id="replay">Play again</button><button class="quiet" id="other">Explore the arcade</button><button class="quiet" id="pledge">Make a green pledge</button></div><p class="mini-label">Scores are stored only in this browser. No shared event leaderboard is connected.</p></div></section>`;$('#save-score').onsubmit=e=>{e.preventDefault();if(state.saved)return;const name=$('#player-name').value.trim();if(!name){$('#player-name').setCustomValidity('Enter your first name.');$('#player-name').reportValidity();return}const rows=read('scores',[]);rows.push({name,mode,score:points,date:new Date().toISOString()});if(write('scores',rows.sort((a,b)=>b.score-a.score).slice(0,100))){state.saved=true;$('#save-score').hidden=true;$('#save-message').innerHTML='<p class="toast">Your score is saved. Thanks for playing!</p>'}else $('#save-message').textContent='Storage is unavailable in this browser. Your score is '+points+'.'};$('#player-name').oninput=()=>$('#player-name').setCustomValidity('');$('#replay').onclick=()=>start(mode);$('#other').onclick=home;$('#pledge').onclick=care;window.scrollTo(0,0)}
function scores(mode='farm'){const rows=read('scores',[]).filter(r=>r.mode===mode).slice(0,10);$('#modal-content').innerHTML=`<span class="eyebrow red">A LITTLE FRIENDLY COMPETITION</span><h2>Our growing legends.</h2><div class="tabs">${Object.entries(titles).map(([key,label])=>`<button class="quiet ${key===mode?'active':''}" data-tab="${key}">${label}</button>`).join('')}</div>${rows.length?rows.map((r,i)=>`<div class="score-row"><span>${i+1}</span><span>${esc(r.name)}<small>${new Date(r.date).toLocaleDateString('en-KE',{day:'numeric',month:'short',timeZone:'Africa/Nairobi'})}</small></span><strong>${r.score}</strong></div>`).join(''):'<p>Your name could be the first here. Complete a game to save your score.</p>'}<p class="pledge-note">High scores on this device only. Names and results stay in this browser.</p>`;document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>scores(b.dataset.tab));if(!modal.open)modal.showModal()}
function care(){const pledge=read('pledge',null);$('#modal-content').innerHTML=`<span class="eyebrow red">CARING FOR THE LAND</span><h2>Let the next chapter<br>take root.</h2><p>CKL’s anniversary story celebrates EcoCare, active since 2010, and its KEPHIS-certified nurseries at Loresho.</p><p style="margin-top:18px">Where would you like CKL to plant a future forest?</p><div class="pledge-options">${['A hillside','A riverbank','A school compound'].map((s,i)=>`<button class="answer" data-vote="${i}">${s}</button>`).join('')}</div><div id="pledge-result" aria-live="polite"></div><p class="pledge-note">This is a personal pledge and an indicative vote saved on this device. It does not commission or confirm a real tree planting.</p>`;document.querySelectorAll('[data-vote]').forEach(b=>b.onclick=()=>{const vote=Number(b.dataset.vote);const votes=read('votes',[0,0,0]);if(pledge!==null)votes[pledge]=Math.max(0,votes[pledge]-1);votes[vote]++;const ok=write('votes',votes)&&write('pledge',vote);showPledge(vote,votes,ok)});if(pledge!==null)showPledge(pledge,read('votes',[0,0,0]),true);if(!modal.open)modal.showModal()}
function showPledge(vote,votes,ok){document.querySelectorAll('[data-vote]').forEach(b=>{b.disabled=true;b.classList.toggle('correct',Number(b.dataset.vote)===vote)});const labels=['A hillside','A riverbank','A school compound'],total=votes.reduce((a,b)=>a+b,0)||1;$('#pledge-result').innerHTML=`<div class="reveal"><strong>One small intention. A greener tomorrow.</strong><p>Your choice: ${labels[vote]}. ${ok?'Your pledge is saved on this device.':'Your browser could not save this pledge.'}</p></div><p class="pledge-note">Votes on this device</p>${votes.map((n,i)=>`<div>${labels[i]} · ${n}<div class="vote-bar"><span style="width:${n/total*100}%"></span></div></div>`).join('')}`}
$('#brand').onclick=()=>state&&!state.locked?exitGame():home();$('#scores').onclick=()=>{if(state&&!state.locked){clearInterval(clock);modal.onclose=()=>{modal.onclose=null;if(state&&!state.locked)startTimer(state.remaining||1)}}scores()};$('#sound').onclick=()=>{sound=!sound;$('#sound').textContent=sound?'Sound on':'Sound off';$('#sound').setAttribute('aria-pressed',String(sound));tone()};$('#fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{say('Fullscreen is unavailable in this browser.')}};$('#close-modal').onclick=()=>modal.close();modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});home();

$('#artwork').onclick=()=>{$('#modal-content').innerHTML='<h2>120 years of growing together.</h2><img src="assets/anniversary.jpeg" alt="Supplied CKL 120-year anniversary artwork with a wooden heritage wheel and Kenyan farm" style="width:100%;height:auto;border-radius:4px">';modal.showModal()};

document.querySelector('#answer-modal').addEventListener('cancel',e=>e.preventDefault());
